using Microsoft.Extensions.Configuration; using CSharer.Core.Config; using CSharer.Core.Services;  namespace CSharer.Console { 	class Program 	{         static async Task Main(string[] args)     	{         	System.Console.WriteLine("🚀 CSharer - Automated Video Publisher\n");          	// Load configuration
         	var config = new ConfigurationBuilder()             	.SetBasePath(Directory.GetCurrentDirectory())             	.AddJsonFile("appsettings.json", optional: false)             	.Build();          	var settings = config.Get<AppSettings>() ?? throw new Exception("Failed to load settings");          	// Initialize services 
                    	var aiService = new AIService(settings.APIs.OpenAI.ApiKey, settings.APIs.OpenAI.Model);         	var bufferService = new BufferService(settings.APIs.Buffer.AccessToken, settings.APIs.Buffer.ProfileIds);         	var pinterestService = new PinterestService(settings.APIs.Pinterest.AccessToken, settings.APIs.Pinterest.BoardId);         	var fileWatcher = new FileWatcherService();          	// Handle new videos 
                                	fileWatcher.OnNewVideoDetected += async (videoPath) =>	         {             	try             	{                 	var fileName = Path.GetFileNameWithoutExtension(videoPath);                                      	System.Console.WriteLine($"📝 Generating caption for: {fileName}");               	  var caption = await aiService.GenerateCaption(fileName);                 	System.Console.WriteLine($"Caption: {caption}");                  	System.Console.WriteLine("📤 Uploading to Buffer...");                 	await bufferService.UploadVideo(videoPath, caption, settings.Defaults.Hashtags);                  	System.Console.WriteLine("📌 Uploading to Pinterest...");                 	await pinterestService.UploadVideoPin(videoPath, caption);                  	System.Console.WriteLine("✅ Done!\n");             	}             	catch (Exception ex)             	{                 	System.Console.WriteLine($"❌ Error: {ex.Message}\n");             	}         	};          	// Start watching 
                                            	fileWatcher.Start(settings.WatchFolder);          	System.Console.WriteLine("\nPress any key to stop...");         	System.Console.ReadKey();                      	fileWatcher.Stop();     	} 	} }